Add-Rule @{ Name = 'FWShift-ADMIN-SSH__port1_-2'; DisplayName = 'ADMIN-SSH (port1) (2)'; Description = 'FWShift: ADMIN-SSH (port1)'; Direction = 'Outbound'; Action = 'Allow'; Enabled = 'False'; Profile = 'Any'; Protocol = 'TCP'; RemotePort = @('22'); LocalAddress = @('192.0.2.50'); RemoteAddress = @('10.20.0.16-10.20.0.255') }
